    ctx.font='9px "DM Mono", monospace';ctx.fillStyle='#8c6544';ctx.fillText('အလွှာ '+mm(Math.min(3,Math.floor(removed/6)+1))+' / ၀၃',cx,bottom+28);
  }
  function drawTray(){
